import pandas as pd
import numpy as np
import re
import warnings
warnings.filterwarnings('ignore')

def number_to_words(n):
    """Convert number to words"""
    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", 
             "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def convert_below_thousand(n):
        if n == 0:
            return ""
        elif n < 10:
            return ones[n]
        elif n < 20:
            return teens[n - 10]
        elif n < 100:
            return tens[n // 10] + (" " + ones[n % 10] if n % 10 != 0 else "")
        else:
            return ones[n // 100] + " hundred" + (" " + convert_below_thousand(n % 100) if n % 100 != 0 else "")

    try:
        n = int(n)
        if n == 0:
            return "zero"

        scales = ["", "thousand", "million", "billion", "trillion"]
        result = []
        scale_idx = 0

        while n > 0:
            if n % 1000 != 0:
                group_words = convert_below_thousand(n % 1000)
                if scales[scale_idx]:
                    group_words += " " + scales[scale_idx]
                result.append(group_words)
            n //= 1000
            scale_idx += 1

        return " ".join(reversed(result))
    except:
        return str(n)

def normalize_token(before, class_hint=None):
    """Apply normalization rules based on the token"""
    before = str(before).strip()

    # PLAIN and PUNCT - usually no change
    if class_hint in ['PLAIN', 'PUNCT', 'VERBATIM']:
        return before

    # LETTERS - spell out
    if class_hint == 'LETTERS':
        clean = before.replace('.', '')
        return ' '.join(c.lower() for c in clean if c.isalpha())

    # CARDINAL - convert to words
    if class_hint == 'CARDINAL':
        return number_to_words(before).lower()

    # DIGITS - spell out each digit
    if class_hint == 'DIGIT':
        ones = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine']
        try:
            return ' '.join(ones[int(d)] for d in str(int(before)))
        except:
            return before

    # Default: return as-is
    return before

